package dev.aura.player;
import android.content.*;import android.graphics.Rect;import android.view.*;import android.widget.*;
/** Reflows existing panes without replacing their view/state on window/posture changes. */
final class AdaptiveMusicPane extends LinearLayout {
 final View primary,secondary;final View spacer;Rect fold=new Rect();boolean horizontal;boolean expanded;boolean dockOnly;float dockFraction,dockTarget;android.animation.ValueAnimator dockMotion;
 AdaptiveMusicPane(Context c,View primary,View secondary){super(c);this.primary=primary;this.secondary=secondary;spacer=new View(c);addView(primary);addView(spacer);addView(secondary);setTag("adaptiveMusicPane");}
 void fold(Rect bounds,boolean horizontal){this.fold=new Rect(bounds);this.horizontal=horizontal;requestLayout();}
 void dock(float fraction,boolean animate){dockTarget=fraction;if(dockMotion!=null)dockMotion.cancel();if(!animate||!Ui.motion(getContext())){dockFraction=fraction;secondary.setTranslationY(0);requestLayout();return;}float start=dockFraction;dockMotion=android.animation.ValueAnimator.ofFloat(start,fraction);dockMotion.setDuration(340);dockMotion.setInterpolator(new android.view.animation.DecelerateInterpolator());dockMotion.addUpdateListener(value->{dockFraction=(float)value.getAnimatedValue();if(start==0&&fraction>0)secondary.setTranslationY(getHeight()*(1-dockFraction/fraction));else if(fraction==0&&start>0)secondary.setTranslationY(getHeight()*(1-dockFraction/start));requestLayout();});dockMotion.addListener(new android.animation.AnimatorListenerAdapter(){@Override public void onAnimationEnd(android.animation.Animator animator){secondary.setTranslationY(0);}});dockMotion.start();}
 void params(View view,LayoutParams next){android.view.ViewGroup.LayoutParams old=view.getLayoutParams();if(old==null||old.width!=next.width||old.height!=next.height)view.setLayoutParams(next);}
 @Override protected void onMeasure(int w,int h){int width=MeasureSpec.getSize(w),height=MeasureSpec.getSize(h);if(dockOnly){boolean allowed=MusicBottomBar.wide(width,getRootView().getHeight()>0?getRootView().getHeight():getResources().getDisplayMetrics().heightPixels,getResources().getDisplayMetrics().density);float f=allowed?dockFraction:0;expanded=f>0;secondary.setVisibility(expanded?VISIBLE:GONE);spacer.setVisibility(GONE);setOrientation(HORIZONTAL);params(primary,new LayoutParams(Math.max(0,Math.round(width*(1-f))),-1));primary.setVisibility(f>=.999f?GONE:VISIBLE);params(secondary,new LayoutParams(Math.max(1,Math.round(width*Math.max(f,dockTarget))),-1));super.onMeasure(w,h);return;}int[] xy=new int[2];getLocationInWindow(xy);Rect hinge=new Rect(fold);hinge.offset(-xy[0],-xy[1]);boolean across=!fold.isEmpty()&&horizontal&&hinge.top>Ui.dp(getContext(),180)&&height-hinge.bottom>Ui.dp(getContext(),180);boolean vertical=!fold.isEmpty()&&!horizontal&&hinge.left>Ui.dp(getContext(),240)&&width-hinge.right>Ui.dp(getContext(),240);expanded=across||vertical||width>=Ui.dp(getContext(),700);secondary.setVisibility(expanded?VISIBLE:GONE);spacer.setVisibility((across||vertical)?VISIBLE:GONE);setOrientation(across?VERTICAL:HORIZONTAL);
  if(across){params(primary,new LayoutParams(-1,hinge.top));params(spacer,new LayoutParams(-1,Math.max(0,hinge.height())));params(secondary,new LayoutParams(-1,Math.max(0,height-hinge.bottom)));}
  else if(vertical){params(primary,new LayoutParams(hinge.left,-1));params(spacer,new LayoutParams(Math.max(0,hinge.width()),-1));params(secondary,new LayoutParams(Math.max(0,width-hinge.right),-1));}
  else{int side=expanded?Math.min(Ui.dp(getContext(),360),(int)(width*.42)):0;params(primary,new LayoutParams(width-side,-1));params(secondary,new LayoutParams(side,-1));}
  super.onMeasure(w,h);
 }
}
